'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useAuth } from '@/contexts/AuthContext';
import { Button } from '@/components/ui/button';
import { Menu, X, User, LogOut, Settings, Home, ShoppingCart, CalendarDays, Users } from 'lucide-react';

const Navbar = () => {
  const { user, logout } = useAuth();
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const handleLogout = async () => {
    await logout();
    setIsMenuOpen(false);
  };

  const isAdmin = user?.role?.name === 'admin';

  return (
    <nav className="bg-white shadow-lg border-b">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16">
          <div className="flex items-center">
            <Link href="/" className="flex-shrink-0 flex items-center">
              <span className="text-2xl font-bold text-orange-600">Restaurant</span>
            </Link>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-8">
            <Link href="/" className="flex items-center text-gray-700 hover:text-orange-600 px-3 py-2 rounded-md text-sm font-medium">
              <Home className="h-4 w-4 mr-2" />
              Trang chủ
            </Link>
            
            {user && (
              <>
                <Link href="/menu" className="flex items-center text-gray-700 hover:text-orange-600 px-3 py-2 rounded-md text-sm font-medium">
                  <ShoppingCart className="h-4 w-4 mr-2" />
                  Menu
                </Link>
                
                <Link href="/reservations" className="flex items-center text-gray-700 hover:text-orange-600 px-3 py-2 rounded-md text-sm font-medium">
                  <CalendarDays className="h-4 w-4 mr-2" />
                  Đặt bàn
                </Link>

                {isAdmin && (
                  <>
                    <Link href="/admin/dashboard" className="flex items-center text-gray-700 hover:text-orange-600 px-3 py-2 rounded-md text-sm font-medium">
                      <Settings className="h-4 w-4 mr-2" />
                      Quản lý
                    </Link>
                    <Link href="/admin/users" className="flex items-center text-gray-700 hover:text-orange-600 px-3 py-2 rounded-md text-sm font-medium">
                      <Users className="h-4 w-4 mr-2" />
                      Người dùng
                    </Link>
                  </>
                )}
              </>
            )}
          </div>

          {/* User Menu */}
          <div className="hidden md:flex items-center space-x-4">
            {user ? (
              <div className="flex items-center space-x-4">
                <span className="text-gray-700">Xin chào, {user.name}</span>
                <Button onClick={handleLogout} variant="outline" size="sm">
                  <LogOut className="h-4 w-4 mr-2" />
                  Đăng xuất
                </Button>
              </div>
            ) : (
              <div className="flex items-center space-x-2">
                <Link href="/auth/login">
                  <Button variant="outline" size="sm">Đăng nhập</Button>
                </Link>
                <Link href="/auth/register">
                  <Button size="sm">Đăng ký</Button>
                </Link>
              </div>
            )}
          </div>

          {/* Mobile menu button */}
          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="text-gray-700 hover:text-orange-600 focus:outline-none focus:text-orange-600"
            >
              {isMenuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Navigation */}
      {isMenuOpen && (
        <div className="md:hidden">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3 bg-gray-50">
            <Link href="/" className="flex items-center text-gray-700 hover:text-orange-600 block px-3 py-2 rounded-md text-base font-medium">
              <Home className="h-4 w-4 mr-2" />
              Trang chủ
            </Link>
            
            {user && (
              <>
                <Link href="/menu" className="flex items-center text-gray-700 hover:text-orange-600 block px-3 py-2 rounded-md text-base font-medium">
                  <ShoppingCart className="h-4 w-4 mr-2" />
                  Menu
                </Link>
                
                <Link href="/reservations" className="flex items-center text-gray-700 hover:text-orange-600 block px-3 py-2 rounded-md text-base font-medium">
                  <CalendarDays className="h-4 w-4 mr-2" />
                  Đặt bàn
                </Link>

                {isAdmin && (
                  <>
                    <Link href="/admin/dashboard" className="flex items-center text-gray-700 hover:text-orange-600 block px-3 py-2 rounded-md text-base font-medium">
                      <Settings className="h-4 w-4 mr-2" />
                      Quản lý
                    </Link>
                    <Link href="/admin/users" className="flex items-center text-gray-700 hover:text-orange-600 block px-3 py-2 rounded-md text-base font-medium">
                      <Users className="h-4 w-4 mr-2" />
                      Người dùng
                    </Link>
                  </>
                )}
              </>
            )}

            <div className="border-t border-gray-200 pt-4">
              {user ? (
                <div className="px-3 py-2">
                  <div className="text-base font-medium text-gray-800 mb-2">
                    Xin chào, {user.name}
                  </div>
                  <Button onClick={handleLogout} variant="outline" size="sm" className="w-full">
                    <LogOut className="h-4 w-4 mr-2" />
                    Đăng xuất
                  </Button>
                </div>
              ) : (
                <div className="px-3 py-2 space-y-2">
                  <Link href="/auth/login" className="block">
                    <Button variant="outline" size="sm" className="w-full">Đăng nhập</Button>
                  </Link>
                  <Link href="/auth/register" className="block">
                    <Button size="sm" className="w-full">Đăng ký</Button>
                  </Link>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;
